#!/usr/bin/env python3
import sys, json

def trunc(s, n=400):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def main(path):
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            typ = obj.get('type')
            ts = obj.get('timestamp', '')
            if typ == 'attachment':
                continue  # hook noise
            msg = obj.get('message')
            if not msg:
                continue
            role = msg.get('role')
            content = msg.get('content')
            if isinstance(content, str):
                print(f"[{ts}] {role}: {trunc(content, 600)}")
                continue
            if not isinstance(content, list):
                continue
            for block in content:
                btype = block.get('type')
                if btype == 'text':
                    txt = block.get('text', '')
                    if txt.strip():
                        print(f"[{ts}] {role} text: {trunc(txt, 600)}")
                elif btype == 'tool_use':
                    name = block.get('name')
                    inp = block.get('input', {})
                    print(f"[{ts}] {role} tool_use {name}: {trunc(json.dumps(inp), 250)}")
                elif btype == 'tool_result':
                    c = block.get('content')
                    if isinstance(c, list):
                        c = ' '.join(x.get('text','') if isinstance(x, dict) else str(x) for x in c)
                    print(f"[{ts}] {role} tool_result: {trunc(c, 200)}")
                elif btype == 'thinking':
                    pass
                else:
                    pass

if __name__ == '__main__':
    main(sys.argv[1])

